#!/usr/bin/env bash
# Generated by build.sh; edit src/, not this file.
IFS= read -r -d '' SB_BUNDLE_PAYLOAD <<'__SB_MANAGER_PAYLOAD__' || :
SB_BUNDLED=1
# Runtime requirements: Bash >=4, jq >=1.6. No eval or sourced user state.
umask 077
set -o pipefail
SB_CORE_VERSION=1.14.4
SB_ROOT=${SB_ROOT:-/etc/sb-manager}
SB_BIN=${SB_BIN:-$SB_ROOT/bin/sing-box}
SB_PROC=${SB_PROC:-/proc}
SB_CGROUP=${SB_CGROUP:-/sys/fs/cgroup}
SB_LOCKED=0
SB_TXN=''
SB_OLD=''
SB_SWITCHED=0
SB_WAS_RUNNING=0
SB_INSTALL_TMP=''
SB_CORE_PENDING=0
say() { printf '%s\n' "$*"; }
err() { printf '错误：%s\n' "$*" >&2; return 1; }
need() { command -v "$1" >/dev/null 2>&1 || err "缺少 $1；请先执行 deps 或按文档安装依赖。"; }
jq_read() { jq -er "$@"; }
random_hex() { openssl rand -hex "${1:-16}"; }
new_uuid() { "$SB_BIN" generate uuid; }
valid_id() { [[ ${1:-} =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$ ]] && [[ $1 != direct && $1 != *--v4 ]]; }
valid_port() { [[ ${1:-} =~ ^[0-9]{1,5}$ ]] && ((10#$1 > 0 && 10#$1 < 65536)); }
valid_domain() {
  local label d=${1:-}
  [[ ${#d} -le 253 && $d == *.* && $d != *[!A-Za-z0-9.-]* && ! $d =~ ^[0-9.]+$ ]] || return 1
  local IFS=.
  for label in $d; do
    [[ $label =~ ^[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?$ ]] || return 1
  done
  [[ $d != .* && $d != *. && $d != *..* ]]
}
valid_address() {
  local a=${1:-} part
  [[ -n $a && $a != *[[:space:]/\\\[\]?#@]* ]] || return 1
  if [[ $a == *:* ]]; then
    valid_ipv6 "$a"
  elif [[ $a =~ ^[0-9.]+$ ]]; then
    [[ $a =~ ^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$ ]] || return 1
    local IFS=.
    for part in $a; do [[ ${#part} -le 3 ]] && ((10#$part <= 255)) || return 1; done
  else valid_domain "$a"; fi
}
valid_ipv6() {
  local a=$1 tail group count=0 compressed=0
  [[ $a != *[!0-9a-fA-F:.]* && $a != *:::* ]] || return 1
  [[ $a != :* || $a == ::* ]] && [[ $a != *: || $a == *:: ]] || return 1
  if [[ $a == *.* ]]; then
    tail=${a##*:}; valid_address "$tail" || return 1
    a=${a%:*}:0000:0000
  fi
  if [[ $a == *::* ]]; then
    compressed=1; tail=${a#*::}; [[ $tail != *::* ]] || return 1
  else [[ $a != :* && $a != *: ]] || return 1; fi
  local IFS=:
  for group in $a; do
    [[ -n $group ]] || continue
    [[ $group =~ ^[0-9a-fA-F]{1,4}$ ]] || return 1
    count=$((count+1))
  done
  if [[ $compressed == 1 ]]; then ((count<8)); else ((count==8)); fi
}
url_encode() { jq -rn --arg x "$1" '$x|@uri'; }
url_decode() {
  local s=$1 out='' hex ch
  while [[ -n $s ]]; do
    if [[ $s == %* ]]; then
      hex=${s:1:2}
      [[ $hex =~ ^[0-9A-Fa-f]{2}$ && $hex != 00 ]] || return 1
      printf -v ch '%b' "\\x$hex"; out+=$ch; s=${s:3}
    else out+=${s:0:1}; s=${s:1}; fi
  done
  printf '%s' "$out"
}
b64_encode() { printf '%s' "$1" | openssl base64 -A; }
b64_decode() {
  local s=${1//-/+}; s=${s//_/\/}
  [[ $s != *[!A-Za-z0-9+/=]* ]] || return 1
  case $((${#s}%4)) in 2) s+='==';; 3) s+='=';; 1) return 1;; esac
  printf '%s' "$s" | openssl base64 -d -A
}
event() {
  [[ -d $SB_ROOT ]] || return 0
  local size=0
  [[ ! -f $SB_ROOT/events.log ]] || size=$(wc -c < "$SB_ROOT/events.log")
  if ((size > 12000)); then mv -f "$SB_ROOT/events.log" "$SB_ROOT/events.log.1" || return 1; fi
  printf '%s %s\n' "$(date -u +%FT%TZ)" "$1" >> "$SB_ROOT/events.log"
}
# Only prompts use this function. EOF and q never become a default value.
ask() {
  local __ask_name=$1 __ask_prompt=$2 __ask_default=${3:-} __ask_input
  printf '%s%s（q 取消）: ' "$__ask_prompt" "${__ask_default:+ [$__ask_default]}" >&2
  IFS= read -r __ask_input || return 130
  [[ $__ask_input != q ]] || return 130
  printf -v "$__ask_name" '%s' "${__ask_input:-$__ask_default}"
}
ask_valid() {
  local __valid_name=$1 __valid_prompt=$2 __valid_default=$3 __valid_check=$4 __valid_value
  while :; do
    ask __valid_value "$__valid_prompt" "$__valid_default" || return 130
    if "$__valid_check" "$__valid_value"; then printf -v "$__valid_name" '%s' "$__valid_value"; return 0; fi
    say '格式无效，请修正。' >&2
  done
}
confirm() { local answer; ask answer "$1，输入 yes 确认" '' || return 130; [[ $answer == yes ]]; }
ask_secret() {
  local __secret_name=$1 __secret_prompt=$2 __secret_existing=${3:-} __secret_value
  printf '%s（回车保留已有值，q 取消）: ' "$__secret_prompt" >&2
  if [[ -t 0 ]]; then IFS= read -rs __secret_value || return 130; printf '\n' >&2
  else IFS= read -r __secret_value || return 130; fi
  [[ $__secret_value != q ]] || return 130
  __secret_value=${__secret_value:-$__secret_existing}
  [[ -n $__secret_value ]] || { err '密码不能为空。'; return 1; }
  printf -v "$__secret_name" '%s' "$__secret_value"
}

# Keep the full generated source in memory before interactive input or installation.
# This also works when Bash reads the entry point from a pipe or /dev/fd.
write_bundle() {
  [[ $'\n'$1$'\n' != *$'\n__SB_MANAGER_PAYLOAD__\n'* ]] || return 1
  printf '%s\n' '#!/usr/bin/env bash' '# Generated by build.sh; edit src/, not this file.' \
    "IFS= read -r -d '' SB_BUNDLE_PAYLOAD <<'__SB_MANAGER_PAYLOAD__' || :" \
    "$1" '__SB_MANAGER_PAYLOAD__' \
    "SB_BUNDLE_PAYLOAD=\${SB_BUNDLE_PAYLOAD%\$'\\n'}" \
    'source <(printf "%s\n" "$SB_BUNDLE_PAYLOAD") || return 1 2>/dev/null || exit 1' \
    'if [[ ${BASH_SOURCE[0]:-} == "$0" || ${#BASH_SOURCE[@]} == 0 ]]; then main "$@"; exit $?; fi'
}

# One capability table drives menus, validation, rendering and port checks.
protocols() {
  cat <<'JSON'
[
 {"id":"reality","name":"VLESS-Reality-Vision","network":"tcp","tls":false,"ws":false},
 {"id":"vless-ws","name":"VLESS-WS","network":"tcp","tls":true,"ws":true},
 {"id":"hysteria2","name":"Hysteria2","network":"udp","tls":true,"ws":false},
 {"id":"tuic","name":"TUIC","network":"udp","tls":true,"ws":false},
 {"id":"trojan","name":"Trojan","network":"tcp","tls":true,"ws":false},
 {"id":"trojan-ws","name":"Trojan-WS","network":"tcp","tls":true,"ws":true},
 {"id":"anytls","name":"AnyTLS","network":"tcp","tls":true,"ws":false},
 {"id":"ss2022","name":"Shadowsocks-2022","network":"both","tls":false,"ws":false},
 {"id":"vmess-ws","name":"VMess-WS","network":"tcp","tls":true,"ws":true},
 {"id":"snell","name":"Snell-v6","network":"tcp","tls":false,"ws":false},
 {"id":"socks","name":"SOCKS5","network":"tcp","tls":false,"ws":false}
]
JSON
}
protocol_field() { protocols | jq -er --arg p "$1" --arg f "$2" '.[]|select(.id==$p)|.[$f]'; }
is_ws() { protocol_field "$1" ws >/dev/null; }
node_network() { protocol_field "$1" network; }
valid_nonempty() { [[ -n $1 && $1 != *$'\r'* && $1 != *$'\n'* ]]; }
valid_listen() { case "$1" in 0.0.0.0|::|127.0.0.1|::1|dual) return 0;; *) return 1;; esac; }
valid_mode() { [[ $1 == direct || $1 == cdn ]]; }
valid_path() { [[ $1 == /* && $1 != *[[:space:]]* && $1 != *'#'* ]]; }
valid_cdn_port() { case "$1" in 443|2053|2083|2087|2096|8443) return 0;; *) return 1;; esac; }
node_set() {
  local file=$1 filter=$2; shift 2
  jq "$@" "$filter" "$file" > "$file.next" && mv -f "$file.next" "$file"
}

validate_state() {
  jq -e --argjson protocols "$(protocols)" '
    def id: type=="string" and test("^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$") and .!="direct" and (endswith("--v4")|not);
    def port: type=="number" and floor==. and .>=1 and .<=65535;
    def host: type=="string" and length>0 and (test("[[:space:]/\\\\\\[\\]?#@]")|not);
    def text: type=="string" and length>0 and all(explode[];.>=32 and .!=127);
    def uuid: type=="string" and test("^[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}$");
    def walkchain($outs;$tag;$seen):
      if $tag=="direct" then true
      elif ($seen|index($tag))!=null then false
      else ([$outs[]|select(.tag==$tag)]|first) as $o |
        if $o==null then false else
          all(([$o.detour//"direct"]+($o.outbounds//[]))[];walkchain($outs;.;$seen+[$tag])) end end;
    . as $s |
    type=="object" and (.nodes|type=="array") and (.outbounds|type=="array") and (.defaults.domain|type=="string") and
    ([.nodes[].id,.outbounds[].tag]|length)==([.nodes[].id,.outbounds[].tag]|unique|length) and
    all(.nodes[];
      . as $n | ([$protocols[]|select(.id==$n.preset)]|first) as $p |
      (.id|id) and $p!=null and
      (.port|port) and (.endpoint.port|port) and (.endpoint.addresses|type=="array" and length>0 and length<=2 and length==(unique|length)) and all(.endpoint.addresses[];host) and
      (.listen|IN("0.0.0.0","::","127.0.0.1","::1","dual")) and
      (.endpoint.mode|IN("direct","cdn")) and
      (if .endpoint.mode=="cdn" then $p.ws and (.endpoint.port|IN(443,2053,2083,2087,2096,8443)) and (.tls.kind|IN("public","origin")) and
        (.endpoint.addresses==[.endpoint.sni]) and .endpoint.host==.endpoint.sni else .tls.kind!="origin" end) and
      (if $p.tls then (.tls.kind|IN("public","origin","self")) and
        (.tls.certificate|type=="array" and length>0 and all(.[];type=="string" and length>0)) and
        (.tls.key|type=="array" and length>0 and all(.[];type=="string" and length>0)) else .tls.kind=="none" end) and
      (if $p.ws then (.ws_path|text and startswith("/") and (test("[[:space:]#]")|not)) and (.endpoint.host|host) else true end) and
      (if (.preset|IN("reality","vless-ws","vmess-ws","tuic")) then (.auth.uuid|uuid) else true end) and
      (if (.preset|IN("hysteria2","tuic","trojan","trojan-ws","anytls","socks")) then (.auth.password|text) else true end) and
      (if .preset=="socks" then (.auth.username|text) else true end) and
      (if .preset=="snell" then (.auth.password|text and utf8bytelength>=12 and utf8bytelength<=255 and (test("[[:space:],]")|not)) else true end) and
      (if .preset=="ss2022" then (.auth.password|type=="string" and test("^[A-Za-z0-9+/]{43}=$")) else true end) and
      (if .preset=="reality" then (.reality.port|port) and (.reality.server|host) and
        (.auth.private_key|type=="string" and test("^[A-Za-z0-9_-]{43}$")) and
        (.auth.public_key|type=="string" and test("^[A-Za-z0-9_-]{43}$")) and
        (.auth.short_id|type=="string" and test("^([0-9a-fA-F]{2}){1,8}$")) else true end) and
      walkchain($s.outbounds;.outbound;[])) and
    all(.outbounds[]; (.tag|id) and (.type|text) and (.tls.insecure//false|not) and walkchain($s.outbounds;.tag;[])) and
    ([.nodes[]|. as $n|{port,network:($protocols[]|select(.id==$n.preset)|.network)}] as $p |
      all(range(0;$p|length); . as $i | all(range($i+1;$p|length); . as $j |
        $p[$i].port!=$p[$j].port or ($p[$i].network!=$p[$j].network and $p[$i].network!="both" and $p[$j].network!="both"))))
  ' "$1" >/dev/null 2>&1 || err '状态不合法：检查字段、端口冲突、CDN 组合、出站引用或循环。'
}
check_core() {
  local diagnostic rc
  [[ -x $SB_BIN ]] || { err '尚未安装官方核心；配置未保存。'; return 1; }
  root_guard && mkdir -p "$SB_ROOT" && chmod 700 "$SB_ROOT" || return 1
  diagnostic=$(mktemp "$SB_ROOT/.check.XXXXXXXX") || return 1
  # Keep only the latest failure, separately from ordinary logs. It may contain secrets.
  if "$SB_BIN" check -c "$1" > "$diagnostic" 2>&1; then
    rm -f "$diagnostic"
  else
    rc=$?
    if chmod 600 "$diagnostic" && mv -f "$diagnostic" "$SB_ROOT/last-check-error.log"; then
      err '官方核心校验失败；使用 check-private failed 在私密终端查看本次错误。'
    else
      rm -f "$diagnostic"
      err '官方核心校验失败，且无法保存私密诊断。'
    fi
    return "$rc"
  fi
}

root_guard() {
  [[ $SB_ROOT == /* && $SB_ROOT != / && $SB_ROOT != /etc && $SB_ROOT != *$'\n'* ]] || { err '数据目录必须是独立绝对路径。'; return 1; }
}
lock_acquire() {
  mkdir -p "$SB_ROOT" || return 1
  chmod 700 "$SB_ROOT" || return 1
  if ! mkdir "$SB_ROOT/lock" 2>/dev/null; then err '另一操作或中断留下的锁存在。确认无管理进程后执行 unlock。'; return 1; fi
  SB_LOCKED=1
  printf '%s\n' "$$" > "$SB_ROOT/lock/pid"
}
lock_release() {
  if [[ $SB_LOCKED == 1 ]]; then rm -f "$SB_ROOT/lock/pid"; rmdir "$SB_ROOT/lock"; SB_LOCKED=0; fi
}
current_generation() {
  local generation
  [[ -f $SB_ROOT/current ]] || return 1
  IFS= read -r generation < "$SB_ROOT/current" || return 1
  [[ $generation =~ ^g\.[A-Za-z0-9]+$ && -d $SB_ROOT/generations/$generation ]] || return 1
  printf '%s' "$SB_ROOT/generations/$generation"
}
state_file() { local d; d=$(current_generation) || return 1; printf '%s/state.json' "$d"; }
empty_state() { printf '%s\n' '{"nodes":[],"outbounds":[],"defaults":{"domain":""}}'; }
txn_begin() {
  root_guard || return 1
  lock_acquire || return 1
  mkdir -p "$SB_ROOT/generations" || { lock_release; return 1; }
  if [[ -e $SB_ROOT/pending || -e $SB_BIN.old ]]; then
    err '存在中断的配置或核心事务；先执行 recover 恢复。'; lock_release; return 1
  fi
  SB_OLD=$(current_generation) || SB_OLD=''
  if [[ -e $SB_ROOT/current && -z $SB_OLD ]]; then err 'current 指针损坏；拒绝初始化覆盖，请恢复备份。'; lock_release; return 1; fi
  SB_TXN=$(mktemp -d "$SB_ROOT/generations/g.XXXXXXXX") || { lock_release; return 1; }
  if [[ -n $SB_OLD ]]; then cp "$SB_OLD/state.json" "$SB_TXN/state.json" || return 1
  else empty_state > "$SB_TXN/state.json"; fi
}
point_to() {
  printf '%s\n' "${1##*/}" > "$SB_ROOT/current.next" && mv -f "$SB_ROOT/current.next" "$SB_ROOT/current"
}
txn_abort() {
  if [[ $SB_SWITCHED == 1 ]]; then
    if [[ -n $SB_OLD ]]; then point_to "$SB_OLD" || return 1; else rm -f "$SB_ROOT/current"; fi
    SB_SWITCHED=0
    if [[ $SB_WAS_RUNNING == 1 ]]; then service_restart || { err '旧配置已恢复，但服务恢复失败，请检查端口与资源。'; return 1; }; fi
  fi
  if [[ $SB_LOCKED == 1 && -n $SB_TXN ]]; then rm -f "$SB_ROOT/pending" "$SB_ROOT/current.next"; fi
  if [[ -n $SB_TXN && $SB_TXN == "$SB_ROOT"/generations/g.* ]]; then rm -rf -- "$SB_TXN"; fi
  SB_TXN=''; SB_OLD=''; SB_WAS_RUNNING=0
  lock_release
}
cleanup() {
  # Remove private debug material while this process still owns the lock.
  if [[ $SB_LOCKED == 1 ]]; then rm -f "$SB_ROOT/debug.json"; fi
  if [[ $SB_CORE_PENDING == 1 ]]; then core_rollback || true; fi
  txn_abort || true
  if [[ -n $SB_INSTALL_TMP && $SB_INSTALL_TMP == "$SB_ROOT"/bin/.install.* ]]; then rm -rf -- "$SB_INSTALL_TMP"; fi
  SB_INSTALL_TMP=''
}
txn_commit() {
  local old=$SB_OLD candidate=$SB_TXN g
  validate_state "$candidate/state.json" && validate_node_certificates "$candidate/state.json" && render_config "$candidate/state.json" "$candidate/config.json" && check_core "$candidate/config.json" || { txn_abort; return 1; }
  chmod 600 "$candidate/state.json" "$candidate/config.json" || { txn_abort; return 1; }
  SB_WAS_RUNNING=0
  service_running && SB_WAS_RUNNING=1
  printf '%s\n' "${old##*/}" > "$SB_ROOT/pending" || { txn_abort; return 1; }
  SB_SWITCHED=1
  point_to "$candidate" || { txn_abort; return 1; }
  if [[ $SB_WAS_RUNNING == 1 ]] && ! service_restart; then
    err '服务应用失败，正在恢复上一代。'; txn_abort; return 1
  fi
  if [[ -n $old ]]; then printf '%s\n' "${old##*/}" > "$SB_ROOT/previous"; fi
  rm -f "$SB_ROOT/pending" || return 1
  SB_SWITCHED=0; SB_TXN=''; SB_OLD=''
  for g in "$SB_ROOT"/generations/g.*; do
    [[ -d $g && $g != "$candidate" && $g != "$old" ]] || continue
    rm -rf -- "$g"
  done
  event 'configuration committed; core check passed'
  say '配置已保存；官方核心校验通过。'
  if [[ $SB_WAS_RUNNING == 1 ]]; then say '服务已重新启动；外网连通未验证。'; else say '服务未启动；外网连通未验证。'; fi
  SB_WAS_RUNNING=0
  lock_release
}
recover() {
  local prior running=0
  confirm '恢复中断事务到先前配置/核心；当前服务将重启' || return 130
  lock_acquire || return 1
  service_running && running=1
  service_stop || return 1
  if [[ -f $SB_ROOT/pending ]]; then
    IFS= read -r prior < "$SB_ROOT/pending" || prior=''
    if [[ -n $prior ]]; then
      [[ $prior =~ ^g\.[A-Za-z0-9]+$ && -f $SB_ROOT/generations/$prior/config.json ]] || { err '恢复指针非法；保留所有文件，请人工检查。'; return 1; }
      point_to "$SB_ROOT/generations/$prior" || return 1
    else rm -f "$SB_ROOT/current"; fi
    rm -f "$SB_ROOT/pending"
  fi
  if [[ -f $SB_BIN.old ]]; then mv -f "$SB_BIN.old" "$SB_BIN" || return 1; fi
  if [[ $running == 1 ]]; then service_start || return 1; fi
  event 'interrupted transaction recovered'
  lock_release
}
state_change() {
  local filter=$1; shift
  jq "$@" "$filter" "$SB_TXN/state.json" > "$SB_TXN/next.json" && mv -f "$SB_TXN/next.json" "$SB_TXN/state.json"
}

new_node() {
  local preset=$1 id=$2 port=$3 address=$4 public_port=$5 uuid password path private='' public='' sid='' keys
  valid_id "$id" && valid_port "$port" && valid_port "$public_port" && valid_address "$address" || { err '名称、端口或连接地址格式无效。'; return 1; }
  protocol_field "$preset" name >/dev/null || return 1
  uuid=$(new_uuid) && password=$(random_hex) && path=$(random_hex 6) || return 1
  if [[ $preset == ss2022 ]]; then password=$(openssl rand -base64 32) || return 1; fi
  if [[ $preset == reality ]]; then
    keys=$("$SB_BIN" generate reality-keypair) || return 1
    private=$(sed -n 's/^PrivateKey: *//p' <<< "$keys")
    public=$(sed -n 's/^PublicKey: *//p' <<< "$keys")
    [[ -n $private && -n $public ]] || return 1
    sid=$(random_hex 4) || return 1
  fi
  jq -n --arg preset "$preset" --arg id "$id" --argjson port "$((10#$port))" --arg a "$address" --argjson p "$((10#$public_port))" \
    --arg uuid "$uuid" --arg password "$password" --arg path "/$path" --arg private "$private" --arg public "$public" --arg sid "$sid" '
    {id:$id,preset:$preset,listen:"0.0.0.0",port:$port,
     endpoint:{addresses:[$a],port:$p,mode:"direct",sni:"",host:""},
     auth:{uuid:$uuid,password:$password,username:"user",private_key:$private,public_key:$public,short_id:$sid},
     tls:{kind:"none"},ws_path:$path,reality:{server:"",port:443},outbound:"direct"}'
}
render_config() {
  jq --argjson protocols "$(protocols)" '
    def inbound:
      . as $n | ($protocols[]|select(.id==$n.preset)) as $p |
      {tag:.id,listen:(if .listen=="dual" then "::" else .listen end),listen_port:.port} +
      (if .preset=="reality" then {type:"vless",users:[{uuid:.auth.uuid,flow:"xtls-rprx-vision"}],tls:{enabled:true,server_name:.endpoint.sni,reality:{enabled:true,handshake:{server:.reality.server,server_port:.reality.port},private_key:.auth.private_key,short_id:[.auth.short_id]}}}
       elif .preset=="vless-ws" then {type:"vless",users:[{uuid:.auth.uuid}]}
       elif .preset=="vmess-ws" then {type:"vmess",users:[{uuid:.auth.uuid}]}
       elif .preset=="ss2022" then {type:"shadowsocks",method:"2022-blake3-aes-256-gcm",password:.auth.password}
       elif .preset=="snell" then {type:"snell",version:6,psk:.auth.password}
       elif .preset=="socks" then {type:"socks",users:[{username:.auth.username,password:.auth.password}]}
       elif .preset=="tuic" then {type:"tuic",users:[{uuid:.auth.uuid,password:.auth.password}],congestion_control:"bbr"}
       else {type:(if .preset=="trojan-ws" then "trojan" else .preset end),users:[{password:.auth.password}]} end) +
      (if ($p.tls|not) then {} else
        {tls:{enabled:true,server_name:.endpoint.sni,certificate:.tls.certificate,key:.tls.key,
         alpn:(if $p.network=="udp" then ["h3"] elif $p.ws then ["http/1.1"] else [] end)}} end) +
      (if $p.ws then {transport:{type:"ws",path:.ws_path}} else {} end);
    {log:{disabled:true},
     inbounds:[.nodes[] | . as $n | inbound | .,
       (if $n.listen=="dual" then .+{tag:($n.id+"--v4"),listen:"0.0.0.0"} else empty end)],
     outbounds:([{type:"direct",tag:"direct"}]+.outbounds),
     route:{final:"direct",rules:[.nodes[]|select(.outbound!="direct")|
       {inbound:([.id]+(if .listen=="dual" then [.id+"--v4"] else [] end)),action:"route",outbound:.outbound}]}}
  ' "$1" > "$2"
}

