certificate_check() {
  local cert=$1 key=$2 domain=$3 kind=$4 a b
  valid_domain "$domain" || { err '证书预期域名无效。'; return 1; }
  openssl x509 -in "$cert" -noout -checkend 0 >/dev/null 2>&1 &&
    openssl x509 -in "$cert" -noout -checkhost "$domain" >/dev/null 2>&1 || { err '证书已过期或域名不匹配。'; return 1; }
  a=$(openssl x509 -in "$cert" -pubkey -noout 2>/dev/null) &&
    b=$(openssl pkey -in "$key" -passin pass: -pubout 2>/dev/null) && [[ $a == "$b" ]] || { err '私钥无法读取或与证书不匹配。'; return 1; }
  # Each trust mode verifies both time bounds, key usage and hostname.
  if [[ $kind == public ]]; then
    openssl verify -purpose sslserver -verify_hostname "$domain" -untrusted "$cert" "$cert" >/dev/null 2>&1 || { err '公开证书链未通过系统 CA 校验；请提供完整链。'; return 1; }
  elif [[ $kind == origin ]]; then
    # Publicly distributed Cloudflare trust roots are bundled, so creation is offline.
    local roots
    roots=$(mktemp "${SB_TXN:-${TMPDIR:-/tmp}}/origin-ca.XXXXXXXX") || return 1
    origin_ca_bundle > "$roots" || { rm -f "$roots"; return 1; }
    if ! openssl verify -CAfile "$roots" -no-CApath -purpose sslserver -verify_hostname "$domain" -untrusted "$cert" "$cert" >/dev/null 2>&1; then
      rm -f "$roots"; err '源站证书未通过 Cloudflare Origin CA 签发链校验。'; return 1
    fi
    rm -f "$roots"
  else
    [[ $kind == self ]] || return 1
    # Explicit leaf trust only for self: verifies both validity bounds without
    # GNU date parsing, which is unavailable in minimal BusyBox containers.
    openssl verify -partial_chain -trusted "$cert" -purpose sslserver -verify_hostname "$domain" "$cert" >/dev/null 2>&1 || { err '证书尚未生效、已过期或用途不正确。'; return 1; }
  fi
}
certificate_attach() {
  local node=$1 kind=$2 domain=$3 cert=${4:-} key=${5:-} dir
  [[ $kind == public || $kind == origin || $kind == self ]] || return 1
  dir=$(mktemp -d "$SB_TXN/cert.XXXXXXXX") || return 1
  if [[ $kind == self ]]; then
    cert=$dir/cert.pem; key=$dir/key.pem
    openssl req -x509 -newkey ec -pkeyopt ec_paramgen_curve:P-256 -nodes -days 365 -subj "/CN=$domain" -addext "subjectAltName=DNS:$domain" -keyout "$key" -out "$cert" >/dev/null 2>&1 || { rm -rf "$dir"; return 1; }
  fi
  certificate_check "$cert" "$key" "$domain" "$kind" || { rm -rf "$dir"; return 1; }
  jq --arg kind "$kind" --arg sni "$domain" --rawfile cert "$cert" --rawfile key "$key" \
    '.endpoint.sni=$sni | .tls={kind:$kind,certificate:[$cert],key:[$key]}' "$node" > "$node.next" && mv -f "$node.next" "$node"
  local rc=$?; rm -rf "$dir"; return "$rc"
}
validate_node_certificates() {
  local state=$1 item kind domain addr dir preset mode value
  value=$(jq -r '.defaults.domain' "$state")
  [[ -z $value ]] || valid_domain "$value" || { err '默认分享域名无效。'; return 1; }
  dir=$(mktemp -d "$SB_TXN/verify.XXXXXXXX") || return 1
  while IFS= read -r item; do
    printf '%s\n' "$item" > "$dir/node.json"
    while IFS= read -r addr; do
      valid_address "$addr" || { rm -rf "$dir"; err '连接地址格式无效。'; return 1; }
    done < <(jq -r '.endpoint.addresses[]' "$dir/node.json")
    kind=$(jq -r .tls.kind "$dir/node.json")
    preset=$(jq -r .preset "$dir/node.json")
    if is_ws "$preset"; then
      value=$(jq -r .endpoint.host "$dir/node.json")
      valid_domain "$value" || { rm -rf "$dir"; err 'WS Host 必须是域名。'; return 1; }
    fi
    if [[ $preset == reality ]]; then
      value=$(jq -r .endpoint.sni "$dir/node.json")
      valid_domain "$value" || { rm -rf "$dir"; return 1; }
      value=$(jq -r .reality.server "$dir/node.json")
      valid_address "$value" || { rm -rf "$dir"; return 1; }
    fi
    [[ $kind != none ]] || continue
    domain=$(jq -r .endpoint.sni "$dir/node.json")
    jq -r '.tls.certificate[]' "$dir/node.json" > "$dir/cert.pem" && jq -r '.tls.key[]' "$dir/node.json" > "$dir/key.pem" || { rm -rf "$dir"; return 1; }
    certificate_check "$dir/cert.pem" "$dir/key.pem" "$domain" "$kind" || { rm -rf "$dir"; return 1; }
  done < <(jq -c '.nodes[]' "$state")
  rm -rf "$dir"
}

# Link contents are credentials. Output only when explicitly requested.
link_export() {
  local node=$1 override=${2:-}
  jq -r --arg address "$override" '
    def enc: @uri;
    . as $n | (if $address!="" then [$address] else .endpoint.addresses end)[] as $a |
    (if ($a|contains(":")) then "["+$a+"]" else $a end) as $host |
    ($host+":"+($n.endpoint.port|tostring)) as $hp |
    ($n.endpoint.sni|enc) as $sni | ($n.id|enc) as $name |
    ("security=tls&sni="+$sni) as $tls |
    ("&type=ws&host="+($n.endpoint.host|enc)+"&path="+($n.ws_path|enc)) as $ws |
    if $n.preset=="reality" then "vless://"+$n.auth.uuid+"@"+$hp+"?security=reality&type=tcp&flow=xtls-rprx-vision&fp=chrome&sni="+$sni+"&pbk="+$n.auth.public_key+"&sid="+$n.auth.short_id+"#"+$name
    elif $n.preset=="vless-ws" then "vless://"+$n.auth.uuid+"@"+$hp+"?"+$tls+$ws+"#"+$name
    elif $n.preset=="vmess-ws" then "vmess://"+({v:"2",ps:$n.id,add:$a,port:$n.endpoint.port,id:$n.auth.uuid,aid:0,scy:"auto",net:"ws",type:"none",tls:"tls",sni:$n.endpoint.sni,host:$n.endpoint.host,path:$n.ws_path}|tojson|@base64)
    elif $n.preset=="ss2022" then "ss://"+(("2022-blake3-aes-256-gcm:"+$n.auth.password)|@base64)+"@"+$hp+"#"+$name
    elif $n.preset=="snell" then $n.id+" = snell, "+$a+", "+($n.endpoint.port|tostring)+", psk="+$n.auth.password+", version=6, mode=default, reuse=false"
    elif $n.preset=="socks" then "socks://"+(($n.auth.username+":"+$n.auth.password)|@base64)+"@"+$hp+"#"+$name
    elif $n.preset=="tuic" then "tuic://"+$n.auth.uuid+":"+($n.auth.password|enc)+"@"+$hp+"?sni="+$sni+"&alpn=h3&congestion_control=bbr&udp_relay_mode=native#"+$name
    elif ($n.preset=="trojan" or $n.preset=="trojan-ws") then "trojan://"+($n.auth.password|enc)+"@"+$hp+"?"+$tls+(if $n.preset=="trojan-ws" then $ws else "&type=tcp" end)+"#"+$name
    else $n.preset+"://"+($n.auth.password|enc)+"@"+$hp+"?sni="+$sni+"#"+$name end
  ' "$node"
  if [[ $(jq -r .tls.kind "$node") == self ]]; then
    say '自签证书：链接未跳过验证；客户端必须另行导入此节点证书为信任锚。' >&2
  fi
}
parse_authority() {
  local authority=$1
  authority=${authority%/}
  if [[ $authority =~ ^\[([0-9a-fA-F:.]+)\]:([0-9]+)$ ]]; then
    LINK_HOST=${BASH_REMATCH[1]}; LINK_PORT=${BASH_REMATCH[2]}
  elif [[ $authority =~ ^([^:]+):([0-9]+)$ ]]; then
    LINK_HOST=${BASH_REMATCH[1]}; LINK_PORT=${BASH_REMATCH[2]}
  else return 1; fi
  valid_address "$LINK_HOST" && valid_port "$LINK_PORT" || return 1
  LINK_PORT=$((10#$LINK_PORT))
}
link_parse() {
  local url=$1 tag=$2 scheme body auth authority user query='' pair k v raw type='tcp' security='' sni='' host='' path='/' pbk='' sid='' flow='' cc=bbr relay=native fp=chrome method='' password='' username='' uuid='' tls='null' transport='null' alpn='[]'
  local -A params=()
  valid_id "$tag" || return 1
  [[ $url == *://* && ${#url} -le 32768 ]] || { err '分享链接格式或长度无效。'; return 1; }
  scheme=${url%%://*}; body=${url#*://}; body=${body%%#*}
  case "$scheme" in vless|trojan|hysteria2|hy2|tuic|anytls|ss|vmess|socks) ;; *) err '不支持此分享链接协议。'; return 1;; esac
  if [[ $scheme == vmess ]]; then
    raw=$(b64_decode "$body") || return 1
    jq -e 'type=="object" and (.aid//0|tonumber)==0 and (.net|IN("tcp","ws")) and (.tls|IN("tls","","none",null))' <<< "$raw" >/dev/null 2>&1 || { err 'VMess 数据或传输不受支持。'; return 1; }
    LINK_HOST=$(jq -r .add <<< "$raw"); LINK_HOST=${LINK_HOST#\[}; LINK_HOST=${LINK_HOST%\]}
    LINK_PORT=$(jq -r .port <<< "$raw"); valid_address "$LINK_HOST" && valid_port "$LINK_PORT" || return 1
    uuid=$(jq -r .id <<< "$raw"); type=$(jq -r '.net//"tcp"' <<< "$raw")
    security=$(jq -r '.tls//"none"' <<< "$raw")
    sni=$(jq -r '[.sni,.host,.add]|map(select(type=="string" and length>0))|first' <<< "$raw")
    host=$(jq -r '[.host,.sni,.add]|map(select(type=="string" and length>0))|first' <<< "$raw")
    path=$(jq -r '.path//"/"' <<< "$raw")
    if ! jq -e '[.allowInsecure,.insecure,.allow_insecure,."skip-cert-verify"]|all(.[];.==null or .==false or .==0 or .=="0" or .=="false")' <<< "$raw" >/dev/null; then err '链接要求跳过证书验证；请改为可信证书或显式信任 CA 后导入 JSON。'; return 1; fi
  else
    if [[ $body == *\?* ]]; then query=${body#*\?}; body=${body%%\?*}; fi
    if [[ $scheme == ss && $body != *@* ]]; then body=$(b64_decode "$body") || return 1; fi
    [[ $body == *@* ]] || return 1
    auth=${body%@*}; authority=${body##*@}
    parse_authority "$authority" || { err '服务器地址或端口无效；IPv6 请使用 [地址]:端口。'; return 1; }
    local IFS='&'
    for pair in $query; do
      [[ $pair == *=* ]] || return 1
      k=${pair%%=*}; v=${pair#*=}
      [[ $k =~ ^[A-Za-z_][A-Za-z0-9_]*$ && ! ${params[$k]+set} ]] || return 1
      case "$k" in type|security|sni|host|path|pbk|sid|flow|congestion_control|udp_relay_mode|fp|alpn|encryption|insecure|allowInsecure|allow_insecure|plugin|obfs) ;; *) err '链接含未支持的参数；请显式导入完整 JSON，避免丢失配置。'; return 1;; esac
      params[$k]=$(url_decode "$v") || return 1
    done
    for k in insecure allowInsecure allow_insecure skip-cert-verify; do
      [[ ${params[$k]:-0} == 0 || ${params[$k]:-false} == false ]] || { err '链接要求跳过 TLS 验证；请导入可信证书配置。'; return 1; }
    done
    [[ -z ${params[plugin]:-} && -z ${params[obfs]:-} ]] || { err '不支持插件或混淆链接。'; return 1; }
    type=${params[type]:-tcp}; security=${params[security]:-}; sni=${params[sni]:-$LINK_HOST}
    host=${params[host]:-$sni}; path=${params[path]:-/}; pbk=${params[pbk]:-}; sid=${params[sid]:-}; flow=${params[flow]:-}
    cc=${params[congestion_control]:-bbr}; relay=${params[udp_relay_mode]:-native}; fp=${params[fp]:-chrome}
    [[ ${params[encryption]:-none} == none ]] || return 1
    user=$(url_decode "$auth") || return 1
    case "$scheme" in
      ss)
        if [[ $user != *:* ]]; then user=$(b64_decode "$user") || return 1; fi
        [[ $user == *:* ]] || return 1
        method=${user%%:*}; password=${user#*:};;
      socks)
        if [[ $user != *:* ]]; then user=$(b64_decode "$user") || return 1; fi
        [[ $user == *:* ]] || return 1; username=${user%%:*}; password=${user#*:};;
      tuic) [[ $user == *:* ]] || return 1; uuid=${user%%:*}; password=${user#*:}; security=tls;;
      vless) uuid=$user; security=${security:-none};;
      *) password=$user; security=tls;;
    esac
  fi
  case "$type" in tcp|'') ;; ws) transport=$(jq -cn --arg p "$path" --arg h "$host" '{type:"ws",path:$p,headers:{Host:$h}}');; *) err '仅支持已验证的 TCP 或 WebSocket 传输。'; return 1;; esac
  case "$scheme" in
    vless|vmess|tuic) [[ $uuid =~ ^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$ ]] || return 1;;
  esac
  if [[ $scheme == hy2 ]]; then scheme=hysteria2; fi
  if [[ $scheme == hysteria2 || $scheme == tuic ]]; then
    [[ $type == tcp ]] || return 1; alpn='["h3"]'
  fi
  if [[ -n ${params[alpn]:-} ]]; then alpn=$(jq -cn --arg a "${params[alpn]}" '$a|split(",")'); fi
  case "$security" in
    tls|reality)
      tls=$(jq -cn --arg sni "$sni" --argjson alpn "$alpn" '{enabled:true,server_name:$sni,alpn:$alpn}')
      if [[ $security == tls && -n ${params[fp]:-} ]]; then
        [[ $scheme != hysteria2 && $scheme != tuic ]] || return 1
        tls=$(jq -c --arg f "$fp" '.+{utls:{enabled:true,fingerprint:$f}}' <<< "$tls")
      fi
      if [[ $security == reality ]]; then
        [[ $scheme == vless && $type == tcp && -n $pbk ]] || return 1
        tls=$(jq -c --arg p "$pbk" --arg s "$sid" --arg f "$fp" '.+{utls:{enabled:true,fingerprint:$f},reality:{enabled:true,public_key:$p,short_id:$s}}' <<< "$tls")
        flow=${flow:-xtls-rprx-vision}
      fi;;
    ''|none) ;; *) return 1;;
  esac
  [[ $cc == bbr || $cc == cubic || $cc == new_reno ]] || return 1
  [[ $relay == native || $relay == quic ]] || return 1
  jq -n --arg tag "$tag" --arg type "$scheme" --arg host "$LINK_HOST" --argjson port "$((10#$LINK_PORT))" --arg uuid "$uuid" --arg pass "$password" --arg user "$username" --arg method "$method" --arg flow "$flow" --arg cc "$cc" --arg relay "$relay" --argjson tls "$tls" --argjson transport "$transport" '
    {type:(if $type=="ss" then "shadowsocks" else $type end),tag:$tag,server:$host,server_port:$port} +
    (if ($type|IN("vless","vmess","tuic")) then {uuid:$uuid} else {} end) +
    (if ($type|IN("trojan","anytls","hysteria2","tuic","ss","socks")) then {password:$pass} else {} end) +
    (if $type=="ss" then {method:$method} elif $type=="socks" then {version:"5",username:$user} elif $type=="vmess" then {security:"auto"} elif $type=="tuic" then {congestion_control:$cc,udp_relay_mode:$relay} else {} end) +
    (if $flow!="" then {flow:$flow} else {} end) +
    (if $tls!=null then {tls:$tls} else {} end) +
    (if $transport!=null then {transport:$transport} else {} end)'
}

detect_arch() {
  local machine=${1:-$(uname -m)} bits=${2:-$(getconf LONG_BIT 2>/dev/null || printf 64)}
  case "$machine" in
    x86_64|amd64) if [[ $bits == 32 ]]; then printf 386; else printf amd64; fi;;
    aarch64|arm64) if [[ $bits == 32 ]]; then printf armv7; else printf arm64; fi;;
    i386|i486|i586|i686) printf 386;; armv7*|armv8l) printf armv7;; armv6*) printf armv6;; armv5*) printf armv5;;
    riscv64|s390x|ppc64le) printf '%s' "$machine";; loongarch64|loong64) printf loong64;; *) return 1;;
  esac
}
network_default() {
  if [[ -f $SB_PROC/net/if_inet6 && $(cat "$SB_PROC/sys/net/ipv6/conf/all/disable_ipv6" 2>/dev/null) != 1 ]]; then
    if [[ $(cat "$SB_PROC/sys/net/ipv6/bindv6only" 2>/dev/null) == 1 ]]; then printf dual; else printf '::'; fi
  else printf 0.0.0.0; fi
}
port_busy() {
  local port=$1 network=$2 file hex seen=0
  hex=$(printf '%04X' "$port")
  for file in "$SB_PROC/net/tcp" "$SB_PROC/net/tcp6" "$SB_PROC/net/udp" "$SB_PROC/net/udp6"; do
    [[ -r $file ]] || continue
    case "$network:$file" in tcp:*/udp*|udp:*/tcp*) continue;; esac
    seen=1
    awk -v port=":$hex" '$2~port"$" && ($4=="0A" || FILENAME~/udp/) {found=1} END {exit !found}' "$file" && return 0
  done
  if [[ $seen == 0 ]] && command -v ss >/dev/null 2>&1; then
    local flags=-lnt
    [[ $network != udp ]] || flags=-lnu
    [[ $network != both ]] || flags=-lntu
    local sockets
    sockets=$(ss "$flags" 2>/dev/null) || return 2
    awk -v p=":$port" '$4~p"$" {found=1} END {exit !found}' <<< "$sockets" && return 0
    return 1
  fi
  [[ $seen != 0 ]] || return 2
  return 1
}
port_free() {
  local port=$1 preset=$2 exclude=${3:-} state=${4:-$SB_TXN/state.json} network rc=0
  network=$(node_network "$preset") || return 2
  if [[ -f $state ]] && jq -e --argjson protocols "$(protocols)" --argjson p "$port" --arg n "$network" --arg ex "$exclude" '
    any(.nodes[]; .id!=$ex and .port==$p and
      (.preset as $p | ($protocols[]|select(.id==$p)|.network) as $t | $t==$n or $t=="both" or $n=="both"))' "$state" >/dev/null; then return 1; fi
  port_busy "$port" "$network" || rc=$?
  case "$rc" in 0) return 1;; 1) return 0;; *) return 2;; esac
}
free_port() {
  local preset=$1 p rc start=${SB_PORT_MIN:-10000} end=${SB_PORT_MAX:-59999}
  for ((p=start; p<=end; p++)); do
    rc=0; port_free "$p" "$preset" || rc=$?
    [[ $rc != 0 ]] || { printf '%s' "$p"; return 0; }
    [[ $rc != 2 ]] || { err '无法检查监听端口：/proc/net 和 ss 均不可用。'; return 1; }
  done
  err '没有可用监听端口。'; return 1
}
free_kb() { df -Pk "$1" | awk 'NR==2 {print $4}'; }
space_check() {
  local dir=$1 need=$2 available
  available=$(free_kb "$dir") || return 1
  [[ $available =~ ^[0-9]+$ ]] || { err '无法读取文件系统剩余空间。'; return 1; }
  ((available >= need)) || { err "安全操作需要剩余 ${need} KiB，实际 ${available} KiB；已中止。"; return 1; }
}
resources() {
  local f limit hostmem _group path controller rest dir effective cpu='unknown' quota period ratio
  hostmem=$(awk '/^MemTotal:/ {printf "%.0f",$2*1024}' "$SB_PROC/meminfo" 2>/dev/null)
  effective=$hostmem
  say "主机/容器视图 MemTotal(bytes): ${hostmem:-未知}"
  # Paths from /proc/self/cgroup cover non-root cgroup membership. Also inspect ancestors.
  if [[ -r $SB_PROC/self/cgroup ]]; then
    while IFS=: read -r _group controller path; do
      [[ $path != *..* ]] || continue
      if [[ -z $controller ]]; then dir=$SB_CGROUP$path
      elif [[ ,$controller, == *,memory,* ]]; then dir=$SB_CGROUP/memory$path
      elif [[ ,$controller, == *,cpu,* ]]; then
        dir=$SB_CGROUP/cpu$path
        [[ -d $dir ]] || dir=$SB_CGROUP/cpu,cpuacct$path
      else continue; fi
      while [[ $dir == "$SB_CGROUP"* ]]; do
        for f in memory.max memory.limit_in_bytes cpu.max cpu.cfs_quota_us cpu.cfs_period_us memory.current memory.usage_in_bytes; do
          if [[ -r $dir/$f ]]; then
            read -r limit rest < "$dir/$f"; say "$dir/$f = $limit ${rest:-}"
            if [[ $f == memory.max || $f == memory.limit_in_bytes ]] && [[ $limit =~ ^[0-9]{1,18}$ ]]; then
              if [[ -z $effective ]] || ((limit<effective)); then effective=$limit; fi
            fi
          fi
        done
        quota=''; period=''
        if [[ -r $dir/cpu.max ]]; then read -r quota period < "$dir/cpu.max"
        elif [[ -r $dir/cpu.cfs_quota_us && -r $dir/cpu.cfs_period_us ]]; then
          read -r quota < "$dir/cpu.cfs_quota_us"; read -r period < "$dir/cpu.cfs_period_us"
        fi
        if [[ $quota =~ ^[0-9]+$ && $period =~ ^[0-9]+$ ]] && ((period>0)); then
          ratio=$(awk -v q="$quota" -v p="$period" -v old="$cpu" 'BEGIN {v=q/p; if(old!="unknown" && old+0<v) v=old; printf "%.4f",v}')
          cpu=$ratio
        fi
        [[ $dir != "$SB_CGROUP" ]] || break
        dir=${dir%/*}
      done
    done < "$SB_PROC/self/cgroup"
  fi
  say "检测到的有效内存上限(bytes): ${effective:-未知}；CPU 配额(核): $cpu（不包含 cpuset 的进一步限制）"
  say '文件系统容量/已用/剩余（不保证等同 LXC 项目配额）：'
  df -Pk "$SB_ROOT" 2>/dev/null || true
  say '数据目录所在挂载（tmpfs 会占用内存；另核实宿主机磁盘配额）：'
  if command -v findmnt >/dev/null 2>&1; then findmnt -T "$SB_ROOT" -o TARGET,FSTYPE,OPTIONS; else say 'findmnt 不可用，请核查 /proc/self/mountinfo。'; fi
  [[ ! -f $SB_BIN ]] || { printf '核心文件字节数: '; wc -c < "$SB_BIN"; }
  say '以上仅为资源检测；没有测量吞吐或证明 128 MB 总配额可用。'
}
refresh_network() {
  local ip4='' ip6='' country='' data
  lock_acquire || return 1
  ip4=$(curl -4 -fsS --connect-timeout 3 --max-time 6 https://api.ipify.org 2>/dev/null) || ip4=''
  ip6=$(curl -6 -fsS --connect-timeout 3 --max-time 6 https://api6.ipify.org 2>/dev/null) || ip6=''
  valid_address "$ip4" || ip4=''; valid_address "$ip6" || ip6=''
  data=$(curl -fsS --connect-timeout 3 --max-time 6 https://ipwho.is/ 2>/dev/null) || data='{}'
  country=$(jq -r '.country_code//"XX"' <<< "$data" 2>/dev/null) || country=XX
  [[ $country =~ ^[A-Z]{2}$ ]] || country=XX
  jq -n --arg v4 "$ip4" --arg v6 "$ip6" --arg country "$country" --arg at "$(date -u +%FT%TZ)" '{ipv4:$v4,ipv6:$v6,country:$country,queried_at:$at}' > "$SB_ROOT/network.next" && mv -f "$SB_ROOT/network.next" "$SB_ROOT/network.json"
  lock_release
  say '查询已结束（空地址表示失败），缓存不影响核心管理。'
}

service_backend() {
  if [[ $SB_ROOT != /etc/sb-manager ]]; then printf process; return 0; fi
  if command -v systemctl >/dev/null 2>&1 && [[ -d /run/systemd/system ]]; then printf systemd
  elif command -v rc-service >/dev/null 2>&1 && [[ -d /run/openrc ]]; then printf openrc
  else printf process; fi
}
service_ownership() {
  local file
  [[ $SB_ROOT == /etc/sb-manager ]] || return 0
  for file in /etc/systemd/system/sb-manager.service /etc/init.d/sb-manager; do
    [[ ! -e $file ]] || grep -q '^# sb-manager-owned$' "$file" || return 1
  done
}
process_start_time() {
  local pid=$1 value
  [[ $pid =~ ^[0-9]+$ ]] || return 1
  # The process can exit between checking /proc and opening stat. Treat that as
  # no longer running, without printing a spurious error during normal shutdown.
  # comm is parenthesized and may contain spaces or parentheses; strip it first.
  value=$(awk '{sub(/^.*\) /, ""); print $20}' "$SB_PROC/$pid/stat" 2>/dev/null) || return 1
  [[ $value =~ ^[0-9]+$ ]] || return 1
  printf '%s' "$value"
}
pid_owned() {
  local pid token actual executable
  [[ -r $SB_ROOT/run.pid && -r $SB_ROOT/run.start ]] || return 1
  read -r pid < "$SB_ROOT/run.pid"; read -r token < "$SB_ROOT/run.start"
  [[ $pid =~ ^[0-9]+$ && -r $SB_PROC/$pid/stat && -e $SB_PROC/$pid/exe ]] || return 1
  kill -0 "$pid" 2>/dev/null || return 1
  actual=$(process_start_time "$pid") || return 1
  [[ $actual == "$token" ]] || return 1
  executable=$(readlink "$SB_PROC/$pid/exe" 2>/dev/null) || return 1
  [[ $executable == "$SB_BIN" ]]
}
service_running() {
  service_ownership || return 1
  case "$(service_backend)" in
    systemd) systemctl is-active --quiet sb-manager 2>/dev/null;;
    openrc) rc-service sb-manager status >/dev/null 2>&1;;
    process) pid_owned;;
  esac
}
run_core() {
  local generation
  generation=$(current_generation) || { err '尚无已校验配置。'; return 1; }
  exec "$SB_BIN" run -c "$generation/config.json"
}
service_start() {
  local generation pid
  service_ownership || { err 'sb-manager 服务名称已被非托管服务占用，拒绝操作。'; return 1; }
  service_running && return 0
  generation=$(current_generation) || return 1
  check_core "$generation/config.json" || return 1
  case "$(service_backend)" in
    systemd) systemctl start sb-manager || return 1;;
    openrc) rc-service sb-manager start || return 1;;
    process)
      [[ -d $SB_PROC/self ]] || { err '后台运行需要 Linux /proc；当前环境仅可进行配置校验。'; return 1; }
      nohup "$SB_BIN" run -c "$generation/config.json" </dev/null >/dev/null 2>&1 &
      pid=$!
      printf '%s\n' "$pid" > "$SB_ROOT/run.pid"
      process_start_time "$pid" > "$SB_ROOT/run.start" || return 1
      say '当前使用后台模式；容器重启后需手动启动或由宿主机 init 调用。';;
  esac
  sleep 1
  service_running || { err '服务没有保持运行；检查监听端口、证书和可用内存。'; return 1; }
  event 'service started (external connectivity not verified)'
}
service_stop() {
  local pid i
  service_ownership || { err '拒绝停止非托管同名服务。'; return 1; }
  case "$(service_backend)" in
    systemd) systemctl stop sb-manager || return 1;;
    openrc) rc-service sb-manager stop || return 1;;
    process)
      if pid_owned; then
        read -r pid < "$SB_ROOT/run.pid"
        kill "$pid" || return 1
        for ((i=0;i<30;i++)); do pid_owned || break; sleep 0.1; done
        if pid_owned; then err '核心未退出，保留 PID 信息；请检查，不强制杀死未知进程。'; return 1; fi
      fi
      rm -f "$SB_ROOT/run.pid" "$SB_ROOT/run.start";;
  esac
  event 'service stopped'
}
service_restart() { service_stop && service_start; }
service_register() {
  # System services use a fixed, separately owned location; custom roots are for tests/foreground use.
  [[ $SB_ROOT == /etc/sb-manager && $SB_BIN == /etc/sb-manager/bin/sing-box ]] || { say '自定义目录：不注册系统服务，可前台运行。'; return 0; }
  local file
  case "$(service_backend)" in
    systemd)
      file=/etc/systemd/system/sb-manager.service
      if [[ -e $file ]] && ! grep -q '^# sb-manager-owned$' "$file"; then err '服务文件已被其他安装占用。'; return 1; fi
      cat > "$file" <<'UNIT'
# sb-manager-owned
[Unit]
Description=sing-box managed by sb-manager
After=network.target
ConditionPathExists=/etc/sb-manager/current
[Service]
Type=simple
ExecStart=/bin/bash /etc/sb-manager/manager.sh run-core
Restart=on-failure
RestartSec=3
UMask=0077
NoNewPrivileges=true
StandardOutput=null
StandardError=null
[Install]
WantedBy=multi-user.target
UNIT
      chmod 644 "$file" && systemctl daemon-reload && systemctl enable sb-manager || return 1;;
    openrc)
      file=/etc/init.d/sb-manager
      if [[ -e $file ]] && ! grep -q '^# sb-manager-owned$' "$file"; then err '服务文件已被其他安装占用。'; return 1; fi
      cat > "$file" <<'UNIT'
#!/sbin/openrc-run
# sb-manager-owned
name="sb-manager"
command="/bin/bash"
command_args="/etc/sb-manager/manager.sh run-core"
command_background="yes"
pidfile="/run/sb-manager.pid"
output_log="/dev/null"
error_log="/dev/null"
start_pre() { test -f /etc/sb-manager/current; }
depend() { need net; }
UNIT
      chmod 755 "$file" && rc-update add sb-manager default || return 1;;
    *) say '无 systemd/OpenRC：不伪造开机自启；请配置宿主机启动钩子。';;
  esac
}
service_unregister() {
  local f
  [[ $SB_ROOT == /etc/sb-manager ]] || return 0
  for f in /etc/systemd/system/sb-manager.service /etc/init.d/sb-manager; do
    [[ -f $f ]] || continue
    grep -q '^# sb-manager-owned$' "$f" || return 1
    if [[ $f == *.service ]]; then systemctl disable sb-manager || return 1
    else rc-update del sb-manager default || return 1; fi
    rm -f "$f" || return 1
  done
  [[ $(service_backend) != systemd ]] || systemctl daemon-reload
}
show_status() {
  [[ ! -x $SB_BIN ]] || "$SB_BIN" version
  if service_running; then say '服务：运行中（未验证外网连通）'; else say '服务：未运行'; fi
  local file
  if file=$(state_file); then jq -r '"节点 \(.nodes|length)，出站 \(.outbounds|length)"' "$file"; else say '尚无配置。'; fi
}

download() { curl --proto '=https' --tlsv1.2 -fL --connect-timeout 10 --max-time 300 --retry 2 -o "$2" "$1"; }
fetch_core_stream() (
  local url=$1 dest=$2 member=$3 maximum=$4 digest=$5 hash_pid='' actual rc=0
  # A short-lived checksum pipe avoids retaining the compressed archive on disk.
  # Only the exact member is emitted; archive paths are never extracted.
  trap '[[ -z $hash_pid ]] || kill "$hash_pid" 2>/dev/null || true' EXIT
  mkfifo "$SB_INSTALL_TMP/hash.pipe" || return 1
  sha256sum < "$SB_INSTALL_TMP/hash.pipe" > "$SB_INSTALL_TMP/digest" & hash_pid=$!
  curl --proto '=https' --tlsv1.2 -fL --connect-timeout 10 --max-time 300 "$url" |
    tee "$SB_INSTALL_TMP/hash.pipe" |
    (ulimit -f "$(((maximum+1023)/1024))" || exit 1; tar -xOzf - "$member") > "$dest" || rc=1
  wait "$hash_pid" || rc=1
  hash_pid=''
  [[ $rc == 0 ]] || return 1
  actual=$(cat "$SB_INSTALL_TMP/digest"); actual=${actual%% *}
  [[ $actual == "${digest#sha256:}" ]] || { err '官方资产摘要不匹配。'; return 1; }
  actual=$(wc -c < "$dest")
  ((actual>0 && actual<=maximum)) || return 1
  rm -f "$SB_INSTALL_TMP/hash.pipe" "$SB_INSTALL_TMP/digest"
)
dependencies() {
  local c missing=0 features
  for c in jq openssl curl tar gzip mkfifo tee sha256sum; do need "$c" || missing=1; done
  [[ $missing == 0 ]] || return 1
  jq -en '1|IN(1,2)' >/dev/null 2>&1 || { err '需要 jq 1.6 或更高版本。'; return 1; }
  features=$(openssl req -help 2>&1 || true)
  [[ $features == *-addext* ]] || { err 'OpenSSL 缺少 req -addext（通常需要 1.1.1+）；请使用受支持的发行版软件包。'; return 1; }
  features=$(openssl x509 -help 2>&1 || true)
  [[ $features == *-checkhost* ]] || { err 'OpenSSL 缺少 x509 -checkhost，无法安全检查证书域名。'; return 1; }
}
install_dependencies() {
  say '将安装 bash/jq/curl/openssl/tar/gzip/CA 证书。包管理器所需空间由发行版决定；不会清理其他软件缓存。'
  confirm '继续安装依赖' || return 130
  if command -v apt-get >/dev/null 2>&1; then apt-get update && apt-get install -y --no-install-recommends bash jq curl openssl tar gzip ca-certificates
  elif command -v apk >/dev/null 2>&1; then apk add --no-cache bash jq curl openssl tar gzip ca-certificates
  elif command -v dnf >/dev/null 2>&1; then dnf install -y --setopt=install_weak_deps=False bash jq curl openssl tar gzip ca-certificates
  elif command -v yum >/dev/null 2>&1; then yum install -y bash jq curl openssl tar gzip ca-certificates
  elif command -v zypper >/dev/null 2>&1; then zypper --non-interactive install --no-recommends bash jq curl openssl tar gzip ca-certificates
  elif command -v pacman >/dev/null 2>&1; then pacman -S --needed bash jq curl openssl tar gzip ca-certificates
  else err '未识别包管理器，请按发行版文档手动安装依赖。'; return 1; fi
  dependencies
}
save_manager() {
  if [[ ${SB_BUNDLED:-0} == 1 ]]; then
    [[ -n ${SB_BUNDLE_PAYLOAD:-} ]] || { err '单文件内容不完整，请重新下载脚本。'; return 1; }
    write_bundle "$SB_BUNDLE_PAYLOAD" > "$SB_ROOT/manager.next" || return 1
  else
    "$BASH" "$SB_SOURCE/build.sh" "$SB_ROOT/manager.next" >/dev/null || return 1
  fi
  "$BASH" -n "$SB_ROOT/manager.next" || return 1
  chmod 700 "$SB_ROOT/manager.next" && mv -f "$SB_ROOT/manager.next" "$SB_ROOT/manager.sh"
}
core_rollback() {
  service_stop || return 1
  if [[ -f $SB_BIN.old ]]; then mv -f "$SB_BIN.old" "$SB_BIN" || return 1
  elif [[ ${SB_INSTALL_HAD_CORE:-0} == 0 ]]; then rm -f "$SB_BIN"; fi
  SB_CORE_PENDING=0
  if [[ ${SB_INSTALL_RUNNING:-0} == 1 ]]; then service_start || return 1; fi
}
install_core() {
  local arch asset version=$SB_CORE_VERSION meta url digest size bound member unpacked generation tmpbin
  [[ $(uname -s) == Linux ]] || { err '安装只支持 Linux；开发机可用官方平台核心执行 check。'; return 1; }
  root_guard && dependencies && lock_acquire || return 1
  mkdir -p "$SB_ROOT/bin" || return 1
  arch=$(detect_arch) || { err '不支持当前架构。'; return 1; }
  [[ ! -e $SB_BIN.old && ! -e $SB_ROOT/pending ]] || { err '存在中断事务，请先执行 recover。'; return 1; }
  case "$arch" in amd64|arm64|386|armv7|riscv64|loong64) asset="sing-box-$version-linux-$arch-musl.tar.gz";; *) asset="sing-box-$version-linux-$arch.tar.gz";; esac
  SB_INSTALL_TMP=$(mktemp -d "$SB_ROOT/bin/.install.XXXXXXXX") || return 1
  meta=$SB_INSTALL_TMP/release.json
  download "https://api.github.com/repos/SagerNet/sing-box/releases/tags/v$version" "$meta" || return 1
  jq -e --arg v "v$version" '.tag_name==$v and .prerelease==false and .draft==false' "$meta" >/dev/null || { err '版本不是已选定的官方稳定发布。'; return 1; }
  url=$(jq -er --arg a "$asset" '.assets[]|select(.name==$a)|.browser_download_url' "$meta") || { err '官方未提供此平台资产；不自动换第三方核心。'; return 1; }
  digest=$(jq -er --arg a "$asset" '.assets[]|select(.name==$a)|.digest|select(startswith("sha256:"))' "$meta") || { err '发布资产无 SHA256 摘要，已停止安装。'; return 1; }
  size=$(jq -er --arg a "$asset" '.assets[]|select(.name==$a)|.size' "$meta") || return 1
  [[ $size =~ ^[0-9]{1,10}$ && $digest =~ ^sha256:[a-f0-9]{64}$ && $url == "https://github.com/SagerNet/sing-box/releases/download/v$version/$asset" ]] || { err '发布元数据格式不符合预期。'; return 1; }
  # amd64 musl measured from the checksum-verified 1.14.4 official archive.
  # Other architectures use a conservative 4x archive bound and a hard file limit.
  if [[ $arch == amd64 && $version == 1.14.4 ]]; then unpacked=92070560; else unpacked=$((size*4)); fi
  bound=$(((unpacked+1023)/1024+8192))
  # Remote du samples exceeded the logical-file model. Provision 128 MiB for
  # candidate allocation plus 8 MiB headroom pending finer filesystem evidence.
  # This is a preflight policy, not a guaranteed peak or a change to the file cap.
  if [[ $arch == amd64 && $version == 1.14.4 ]]; then bound=139264; fi
  space_check "$SB_ROOT/bin" "$bound" || return 1
  say "下载前空间门槛：额外 $bound KiB（候选核心及分配余量；压缩包不落盘、旧核心保留；非峰值保证）。"
  member=${asset%.tar.gz}/sing-box
  tmpbin=$SB_INSTALL_TMP/sing-box
  fetch_core_stream "$url" "$tmpbin" "$member" "$unpacked" "$digest" || { err '流式下载、解压或摘要校验失败；有效核心保留。'; return 1; }
  chmod 700 "$tmpbin" || return 1
  "$tmpbin" version >/dev/null 2>&1 || { err '核心无法在当前架构/用户态运行；旧核心未替换。'; return 1; }
  generation=$(current_generation) || generation=''
  if [[ -n $generation ]]; then "$tmpbin" check -c "$generation/config.json" >/dev/null 2>&1 || { err '新核心不接受现有配置；旧核心未替换。'; return 1; }; fi
  save_manager || return 1
  service_register || return 1
  SB_INSTALL_RUNNING=0; service_running && SB_INSTALL_RUNNING=1
  if [[ $SB_INSTALL_RUNNING == 1 ]]; then service_stop || return 1; fi
  [[ ! -e $SB_BIN.old ]] || { err '发现未完成更新备份；请先恢复。'; return 1; }
  SB_INSTALL_HAD_CORE=0; [[ ! -f $SB_BIN ]] || SB_INSTALL_HAD_CORE=1
  SB_CORE_PENDING=1
  if [[ -f $SB_BIN ]]; then mv "$SB_BIN" "$SB_BIN.old" || return 1; fi
  mv "$tmpbin" "$SB_BIN" || { core_rollback; return 1; }
  if [[ $SB_INSTALL_RUNNING == 1 ]] && ! service_start; then core_rollback; err '新核心启动失败，已尝试恢复旧核心。'; return 1; fi
  SB_CORE_PENDING=0
  rm -f "$SB_BIN.old"
  rm -rf "$SB_INSTALL_TMP"; SB_INSTALL_TMP=''
  event 'official core installed/updated'
  lock_release
  say "官方核心 $version 已安装。已有运行服务已尝试恢复；新安装不会自动创建节点或启动服务。"
}
uninstall_core() {
  local mode=$1
  [[ $mode == keep || $mode == purge ]] || return 1
  confirm "卸载核心（$mode：keep 保留配置，purge 删除托管数据）" || return 130
  lock_acquire || return 1
  service_stop && service_unregister || return 1
  [[ $SB_BIN == "$SB_ROOT/bin/sing-box" ]] || { err '拒绝删除非托管核心路径。'; return 1; }
  rm -f "$SB_BIN" "$SB_BIN.old" "$SB_ROOT/manager.sh" || return 1
  lock_release
  if [[ $mode == purge ]]; then
    [[ $SB_ROOT == /etc/sb-manager ]] || { err '自定义目录不自动递归删除；核心已卸载，配置保留。'; return 1; }
    rm -rf -- "$SB_ROOT" || return 1
  fi
  say '卸载完成。'
}

put_node() {
  local file=$1 mode=${2:-add} id preset port oldport oldpreset
  id=$(jq -er .id "$file") && valid_id "$id" || return 1
  preset=$(jq -er .preset "$file") && port=$(jq -er .port "$file") && valid_port "$port" || return 1
  if [[ $mode == add ]]; then
    jq -e --arg id "$id" 'any(.nodes[];.id==$id) or any(.outbounds[];.tag==$id)' "$SB_TXN/state.json" >/dev/null && { err '名称已存在。'; return 1; }
  else
    jq -e --arg id "$id" 'any(.nodes[];.id==$id)' "$SB_TXN/state.json" >/dev/null || return 1
  fi
  oldport=$(jq -r --arg id "$id" '.nodes[]|select(.id==$id)|.port' "$SB_TXN/state.json")
  oldpreset=$(jq -r --arg id "$id" '.nodes[]|select(.id==$id)|.preset' "$SB_TXN/state.json")
  if [[ $port != "$oldport" || $preset != "$oldpreset" ]]; then
    port_free "$port" "$preset" "$id" || { err '监听端口与已有节点或系统服务冲突。'; return 1; }
  fi
  state_change '.nodes = ([.nodes[]|select(.id!=$n[0].id)]+$n)' --slurpfile n "$file"
}
put_outbound() {
  local file=$1 mode=${2:-add} id
  jq -e 'type=="object" and (.tag|type=="string") and (.type|type=="string") and (.tls.insecure//false|not)' "$file" >/dev/null || { err '需要包含 type/tag 的单个出站对象；TLS 不能跳过校验。'; return 1; }
  id=$(jq -er .tag "$file"); valid_id "$id" || return 1
  if [[ $mode == add ]]; then
    jq -e --arg id "$id" 'any(.nodes[];.id==$id) or any(.outbounds[];.tag==$id)' "$SB_TXN/state.json" >/dev/null && { err '名称已存在。'; return 1; }
  else jq -e --arg id "$id" 'any(.outbounds[];.tag==$id)' "$SB_TXN/state.json" >/dev/null || return 1; fi
  state_change '.outbounds=([.outbounds[]|select(.tag!=$o[0].tag)]+$o)' --slurpfile o "$file"
}
delete_resource() {
  local kind=$1 id=$2
  valid_id "$id" || return 1
  if [[ $kind == node ]]; then
    jq -e --arg id "$id" 'any(.nodes[];.id==$id)' "$SB_TXN/state.json" >/dev/null || return 1
    state_change '.nodes|=map(select(.id!=$id))' --arg id "$id"
  elif [[ $kind == outbound ]]; then
    jq -e --arg id "$id" 'any(.outbounds[];.tag==$id)' "$SB_TXN/state.json" >/dev/null || return 1
    if jq -e --arg id "$id" 'any(.outbounds[];.detour==$id or ((.outbounds//[])|index($id))!=null)' "$SB_TXN/state.json" >/dev/null; then err '其他出站引用了此出口；请先修改链式/选择器关系。'; return 1; fi
    state_change '.outbounds|=map(select(.tag!=$id)) | .nodes|=map(if .outbound==$id then .outbound="direct" else . end)' --arg id "$id"
  else return 1; fi
}
bind_nodes() {
  local out=$1; shift
  local selected id
  [[ $out == direct ]] || valid_id "$out" || return 1
  if [[ $out != direct ]]; then jq -e --arg o "$out" 'any(.outbounds[];.tag==$o)' "$SB_TXN/state.json" >/dev/null || return 1; fi
  (($#>0)) || return 1
  if [[ $1 == all && $# == 1 ]]; then selected=$(jq -c '[.nodes[].id]' "$SB_TXN/state.json")
  else
    for id in "$@"; do valid_id "$id" && jq -e --arg id "$id" 'any(.nodes[];.id==$id)' "$SB_TXN/state.json" >/dev/null || return 1; done
    selected=$(printf '%s\n' "$@" | jq -Rsc 'split("\n")[:-1]|unique')
  fi
  state_change '.nodes|=map(. as $n|if ($ids|index($n.id))!=null then .outbound=$o else . end)' --arg o "$out" --argjson ids "$selected"
}
list_nodes() {
  local file
  file=$(state_file) || { say '暂无节点。'; return 0; }
  jq -r '.nodes[]|"\(.id)  \(.preset)\n  监听 \(.listen):\(.port) → 公网 \(.endpoint.addresses|join(",")):\(.endpoint.port)\n  出口 \(.outbound)；证书 \(.tls.kind)；模式 \(.endpoint.mode)"' "$file"
}
list_outbounds() {
  local file; file=$(state_file) || return 0
  jq -r '.outbounds[]|"\(.tag)  \(.type)  \(.server):\(.server_port)  detour=\(.detour//"direct")"' "$file"
}
show_links() {
  local id=${1:-all} file node domain temp
  file=$(state_file) || return 1
  jq -e --arg id "$id" 'any(.nodes[];$id=="all" or .id==$id)' "$file" >/dev/null || { err '没有匹配的节点。'; return 1; }
  domain=$(jq -r '.defaults.domain//""' "$file")
  temp=$(mktemp) || return 1
  while IFS= read -r node; do
    printf '%s\n' "$node" > "$temp"
    if [[ $(jq -r .endpoint.mode "$temp") == cdn ]]; then link_export "$temp" || { rm -f "$temp"; return 1; }
    else link_export "$temp" "$domain" || { rm -f "$temp"; return 1; }; fi
  done < <(jq -c --arg id "$id" '.nodes[]|select($id=="all" or .id==$id)' "$file")
  rm -f "$temp"
}
client_config() (
  # A complete minimal sing-box client; explicit export contains credentials.
  local id=$1 file temp link domain preset
  valid_id "$id" || return 1
  file=$(state_file) || return 1
  temp=$(mktemp -d) || return 1
  trap 'rm -rf "$temp"' EXIT
  jq -e --arg id "$id" '.nodes[]|select(.id==$id)' "$file" > "$temp/node.json" || return 1
  domain=$(jq -r '.defaults.domain' "$file")
  [[ $(jq -r .endpoint.mode "$temp/node.json") != cdn ]] || domain=''
  node_set "$temp/node.json" '.endpoint.addresses=[.endpoint.addresses[0]]' || return 1
  preset=$(jq -r .preset "$temp/node.json")
  if [[ $preset == snell ]]; then
    jq --arg d "$domain" '{type:"snell",tag:"proxy",server:(if $d!="" then $d else .endpoint.addresses[0] end),server_port:.endpoint.port,version:6,psk:.auth.password}' "$temp/node.json" > "$temp/out.json" || return 1
  else
    link=$(link_export "$temp/node.json" "$domain") || return 1
    link_parse "$link" proxy > "$temp/out.json" || return 1
  fi
  if [[ $(jq -r .tls.kind "$temp/node.json") == self ]]; then
    node_set "$temp/out.json" '.tls.certificate=$n[0].tls.certificate' --slurpfile n "$temp/node.json" || return 1
  fi
  jq -n --slurpfile o "$temp/out.json" '{log:{disabled:true},inbounds:[{type:"mixed",tag:"local",listen:"127.0.0.1",listen_port:2080}],outbounds:$o,route:{final:"proxy"}}' > "$temp/client.json" || return 1
  check_core "$temp/client.json" || return 1
  cat "$temp/client.json"
)
export_certificate() {
  local id=$1 file; valid_id "$id" || return 1; file=$(state_file) || return 1
  jq -er --arg id "$id" '.nodes[]|select(.id==$id)|.tls.certificate[]' "$file"
}
set_domain() {
  local domain=$1
  [[ -z $domain ]] || valid_domain "$domain" || return 1
  state_change '.defaults.domain=$d' --arg d "$domain"
}
mutate() {
  txn_begin || return 1
  "$@" && txn_commit || { txn_abort; return 1; }
}
import_nodes() {
  local file=$1 item
  jq -e 'type=="array" and length>0' "$file" >/dev/null || return 1
  while IFS= read -r item; do
    printf '%s\n' "$item" > "$SB_TXN/import-node.json"
    put_node "$SB_TXN/import-node.json" || return 1
  done < <(jq -c '.[]' "$file")
  rm -f "$SB_TXN/import-node.json"
}
set_detour() {
  local id=$1 target=$2
  valid_id "$id" || return 1
  [[ $target == direct ]] || valid_id "$target" || return 1
  jq -e --arg id "$id" 'any(.outbounds[];.tag==$id)' "$SB_TXN/state.json" >/dev/null || return 1
  state_change '.outbounds|=map(if .tag==$id then (if $target=="direct" then del(.detour) else .detour=$target end) else . end)' --arg id "$id" --arg target "$target"
}

certificate_wizard() {
  local file=$1 domain=$2 mode=$3 kind cert='' key=''
  if [[ $mode == cdn ]]; then
    say 'CDN 源站证书：1 公开可信完整链；2 Cloudflare Origin CA（仅源站使用）。'
  else
    say '直连证书：1 公开可信完整链；3 自签（客户端必须另行导入信任）。'
  fi
  while :; do
    ask kind '证书类型' 1 || return 130
    case "$mode:$kind" in
      *:1) kind=public; break;; cdn:2) kind=origin; break;; direct:3) kind=self; break;;
      *) say '此模式不支持该证书类型。';;
    esac
  done
  if [[ $kind != self ]]; then
    ask_valid cert '完整证书链 PEM 路径' '' valid_nonempty || return 130
    ask_valid key '未加密私钥 PEM 路径' '' valid_nonempty || return 130
  fi
  certificate_attach "$file" "$kind" "$domain" "$cert" "$key"
}

node_wizard() {
  local preset=$1 edit=${2:-} file=$SB_TXN/node.json id port public_port address second='' sni='' host='' path='' mode=direct listen old_sni='' oldmode=direct oldport='' prefix=XX change target target_port advanced oldpublic=''
  if [[ -n $edit ]]; then
    jq -e --arg id "$edit" '.nodes[]|select(.id==$id)' "$SB_TXN/state.json" > "$file" || return 1
    preset=$(jq -r .preset "$file"); id=$edit
    oldport=$(jq -r .port "$file"); oldpublic=$(jq -r .endpoint.port "$file")
    old_sni=$(jq -r .endpoint.sni "$file"); oldmode=$(jq -r .endpoint.mode "$file")
    second=$(jq -r '.endpoint.addresses[1]//""' "$file")
  else
    [[ ! -r $SB_ROOT/network.json ]] || prefix=$(jq -r '.country//"XX"' "$SB_ROOT/network.json")
    ask_valid id '节点名称（字母/数字/点/短横线）' "$prefix-$preset-$(random_hex 2)" valid_id || return 130
  fi
  protocol_field "$preset" name >/dev/null || return 1
  if is_ws "$preset"; then
    say '1 直连 TLS；2 Cloudflare CDN（需要自己管理的域名）。'
    change=1; [[ $oldmode != cdn ]] || change=2
    while :; do
      ask change '连接方式' "$change" || return 130
      case "$change" in 1) mode=direct; break;; 2) mode=cdn; break;; *) say '请选择 1 或 2。'; change=1;; esac
    done
  fi
  address=$(jq -r '.defaults.domain//""' "$SB_TXN/state.json")
  if [[ -z $address && -r $SB_ROOT/network.json ]]; then address=$(jq -r '[.ipv4,.ipv6]|map(select(.!=""))|first//""' "$SB_ROOT/network.json"); fi
  [[ -z $edit ]] || address=$(jq -r '.endpoint.addresses[0]' "$file")
  if [[ $mode == cdn ]]; then
    valid_domain "$address" || address=''
    say '域名需解析到源站并开启 Cloudflare 代理、WebSocket，SSL/TLS 使用 Full (strict)。'
    ask_valid address 'CDN 业务域名（例如 proxy.example.com）' "$address" valid_domain || return 130
    public_port=443; [[ $oldmode != cdn ]] || public_port=${oldpublic:-443}
    ask_valid public_port '客户端连接 CDN 的 HTTPS 端口' "$public_port" valid_cdn_port || return 130
    port=${oldport:-$public_port}
    say '默认源站端口与 CDN 端口相同；只有已配置 Origin Rule、NAT 或反向代理映射时才使用不同端口。'
  else
    ask_valid address '客户端连接地址（公网 IP / 域名 / 裸 IPv6）' "$address" valid_address || return 130
    port=$oldport; [[ -n $port ]] || port=$(free_port "$preset") || return 1
  fi
  while :; do
    ask_valid port '服务端监听端口' "$port" valid_port || return 130
    port=$((10#$port))
    [[ $port == "$oldport" ]] && break
    port_free "$port" "$preset" "$id" && break
    say '端口已占用或无法检查，请选择可用端口。'
  done
  if [[ $mode == direct ]]; then
    public_port=${oldpublic:-$port}
    ask_valid public_port '客户端连接端口（NAT 映射端口）' "$public_port" valid_port || return 130
  elif [[ $port != "$public_port" ]]; then
    confirm "CDN $public_port 到监听 $port 的端口映射已配置" || return 130
  fi
  [[ -n $edit ]] || new_node "$preset" "$id" "$port" "$address" "$public_port" > "$file" || return 1
  node_set "$file" '.port=$p|.endpoint.port=$pp|.endpoint.addresses=[$a]|.endpoint.mode=$m' --argjson p "$port" --argjson pp "$((10#$public_port))" --arg a "$address" --arg m "$mode" || return 1
  if [[ $mode == direct && -n $second ]]; then node_set "$file" '.endpoint.addresses+=[$a]' --arg a "$second" || return 1; fi
  listen=$(network_default); [[ -z $edit ]] || listen=$(jq -r .listen "$file")
  ask advanced "监听默认为 $listen；输入 yes 展开监听范围和备用连接地址" no || return 130
  if [[ $advanced == yes ]]; then
    ask_valid listen '监听：0.0.0.0 / :: / dual / 127.0.0.1 / ::1' "$listen" valid_listen || return 130
    if [[ $mode == direct ]]; then
      ask second '备用连接地址（回车保留，- 清除）' "$second" || return 130
      if [[ -n $second && $second != - ]]; then
        valid_address "$second" || { err '备用地址无效。'; return 1; }
        node_set "$file" '.endpoint.addresses=[$a,$b]' --arg a "$address" --arg b "$second" || return 1
      else node_set "$file" '.endpoint.addresses=[$a]' --arg a "$address" || return 1; fi
    fi
  fi
  node_set "$file" '.listen=$l' --arg l "$listen" || return 1
  case "$preset" in
    reality)
      ask_valid sni 'REALITY 握手目标 SNI' "$old_sni" valid_domain || return 130
      target=$(jq -r .reality.server "$file"); target_port=$(jq -r .reality.port "$file")
      ask_valid target 'REALITY 握手目标地址' "${target:-$sni}" valid_address || return 130
      ask_valid target_port '目标握手端口' "$target_port" valid_port || return 130
      node_set "$file" '.endpoint.sni=$s|.reality={server:$h,port:$p}' --arg s "$sni" --arg h "$target" --argjson p "$((10#$target_port))" || return 1;;
    ss2022|snell|socks) ;;
    *)
      if [[ $mode == cdn ]]; then sni=$address
      else
        sni=$old_sni; [[ -n $sni ]] || { valid_domain "$address" && sni=$address; }
        ask_valid sni 'TLS 证书域名 / 客户端 SNI（必须与证书匹配）' "$sni" valid_domain || return 130
      fi
      change=yes
      if [[ -n $edit && $sni == "$old_sni" && $oldmode == "$mode" ]]; then
        ask change '替换证书？yes 替换；回车保留' no || return 130
      fi
      if [[ $change == yes ]]; then certificate_wizard "$file" "$sni" "$mode" || return $?; fi;;
  esac
  if is_ws "$preset"; then
    path=$(jq -r .ws_path "$file")
    ask_valid path 'WebSocket 路径（客户端和源站一致）' "$path" valid_path || return 130
    if [[ $mode == cdn ]]; then host=$address
    else
      host=$(jq -r .endpoint.host "$file")
      ask_valid host 'WebSocket Host' "${host:-$sni}" valid_domain || return 130
    fi
    node_set "$file" '.ws_path=$p|.endpoint.host=$h' --arg p "$path" --arg h "$host" || return 1
  fi
  if [[ -n $edit ]]; then
    ask change '重新生成认证信息（UUID / 密码 / REALITY 密钥）？yes 更新；回车保留' no || return 130
    if [[ $change == yes ]]; then
      new_node "$preset" "$id" "$port" "$address" "$public_port" > "$SB_TXN/auth.json" || return 1
      node_set "$file" '.auth=$n[0].auth' --slurpfile n "$SB_TXN/auth.json" || return 1
      rm -f "$SB_TXN/auth.json"
    fi
  fi
  say "$id / $preset / $mode"
  say "客户端 $address:$public_port → 监听 $listen:$port；SNI=${sni:-无}；Host=${host:-无}"
  [[ $mode != cdn ]] || say '请先完成 DNS、CDN、证书及源站端口映射；工具不代替 CDN 控制台配置。'
  if [[ -n $edit ]]; then put_node "$file" edit; else put_node "$file" add; fi
  local rc=$?; CREATED_NODE_ID=$id; rm -f "$file"; return "$rc"
}

create_wizard() {
  local choice token preset rc
  local -a selected=() presets=() created=()
  protocols | jq -r 'to_entries[]|"\(.key+1)) \(.value.name)"'
  say '0) 返回；空格/逗号多选；整批校验后统一保存。'
  ask choice '请选择协议' '' || return 130
  [[ -n $choice && $choice != 0 ]] || return 0
  choice=${choice//,/ }; choice=${choice//，/ }; read -r -a selected <<< "$choice"
  for token in "${selected[@]}"; do
    [[ $token =~ ^([1-9]|10|11)$ ]] || { err '无效协议序号。'; return 1; }
    preset=$(protocols | jq -r --argjson i "$token" '.[$i-1].id') || return 1
    presets+=("$preset")
  done
  txn_begin || return 1
  for preset in "${presets[@]}"; do
    node_wizard "$preset" || { rc=$?; txn_abort; return "$rc"; }
    created+=("$CREATED_NODE_ID")
  done
  confirm "保存以上 ${#presets[@]} 个节点" && txn_commit || { rc=$?; txn_abort; return "$rc"; }
  for token in "${created[@]}"; do show_links "$token" || return 1; done
}

outbound_wizard() {
  local edit=${1:-} choice tag type server port user='' password='' psk file=$SB_TXN/outbound.json source link detour='' value field
  if [[ -n $edit ]]; then
    jq -e --arg id "$edit" '.outbounds[]|select(.tag==$id)' "$SB_TXN/state.json" > "$file" || return 1
    tag=$edit
    say '编辑：1 修改服务器/端口/认证（保留其他字段）；2 用新分享链接替换；3 用 JSON 替换'
    ask choice '选择' 1 || return 130
  else
    ask_valid tag '出站名称，例如 exit-us' "exit-$(random_hex 2)" valid_id || return 130
    say '1 手动 SOCKS5 / HTTP / Snell；2 分享链接；3 自定义 JSON'
    ask choice '选择' 2 || return 130
  fi
  case "$choice" in
    1)
      if [[ -n $edit ]]; then type=$(jq -r .type "$file"); server=$(jq -r .server "$file"); port=$(jq -r .server_port "$file")
      else
        ask type '协议：socks / http / snell' socks || return 130
        case "$type" in socks|http|snell) ;; *) return 1;; esac
        server=''; port=1080
        jq -n --arg tag "$tag" --arg type "$type" '{tag:$tag,type:$type}' > "$file"
      fi
      ask_valid server '出口服务器地址（裸 IPv6 / IP / 域名）' "$server" valid_address || return 130
      ask_valid port '出口服务器端口' "$port" valid_port || return 130
      node_set "$file" '.server=$s | .server_port=$p' --arg s "$server" --argjson p "$((10#$port))" || return 1
      case "$type" in
        socks|http)
          user=$(jq -r '.username//""' "$file")
          ask user '认证用户名（- 为无认证）' "${user:--}" || return 130
          if [[ $user != - ]]; then
            password=$(jq -r '.password//""' "$file")
            ask_secret password '出口认证密码' "$password" || return 130
            node_set "$file" '.username=$u|.password=$p' --arg u "$user" --arg p "$password" || return 1
          else node_set "$file" 'del(.username,.password)' || return 1; fi
          [[ $type != socks ]] || node_set "$file" '.version="5"' || return 1;;
        snell)
          psk=$(jq -r '.psk//""' "$file"); [[ -n $psk ]] || psk=$(random_hex)
          ask_secret psk 'Snell v6 PSK（12–255 字节）' "$psk" || return 130
          node_set "$file" '.version=6|.psk=$p' --arg p "$psk" || return 1;;
        *)
          for field in uuid password; do
            value=$(jq -r --arg f "$field" '.[$f]//""' "$file")
            [[ -n $value ]] || continue
            ask_secret value "$field" "$value" || return 130
            node_set "$file" '.[$f]=$v' --arg f "$field" --arg v "$value" || return 1
          done;;
      esac;;
    2) ask_secret link '粘贴分享链接（不回显）' '' || return 130; link_parse "$link" "$tag" > "$file" || return 1;;
    3)
      ask_valid source '单个出站 JSON 文件路径' '' valid_nonempty || return 130
      jq --arg tag "$tag" '.tag=$tag' "$source" > "$file" || return 1;;
    *) return 1;;
  esac
  detour=$(jq -r '.detour//"direct"' "$file")
  ask detour '通过哪个已有出口连接此服务器？direct 直接连接，或填写出站名称' "$detour" || return 130
  if [[ $detour == direct ]]; then node_set "$file" 'del(.detour)' || return 1
  else node_set "$file" '.detour=$d' --arg d "$detour" || return 1; fi
  if [[ -n $edit ]]; then put_outbound "$file" edit; else put_outbound "$file" add; fi
  local rc=$?; rm -f "$file"; return "$rc"
}
outbound_menu() {
  local choice id out raw
  local -a ids=()
  list_outbounds
  say '1 新增出口；2 修改出口；3 删除出口；4 绑定节点；5 恢复直连；0 返回'
  ask choice '选择' '' || return 130
  case "$choice" in
    1) txn_begin && outbound_wizard && confirm '保存出站' && txn_commit;;
    2) ask_valid id '出站名称' '' valid_id && txn_begin && outbound_wizard "$id" && confirm '保存出站修改' && txn_commit;;
    3) ask_valid id '出站名称' '' valid_id && confirm '删除出口；引用此出口的节点会恢复直连' && mutate delete_resource outbound "$id";;
    4|5)
      list_nodes
      ask raw '节点名称（空格/逗号分隔；all 全部；回车取消）' '' || return 130
      [[ -n $raw ]] || return 0; raw=${raw//,/ }; raw=${raw//，/ }; read -r -a ids <<< "$raw"
      out=direct
      [[ $choice != 4 ]] || ask out '出口名称' '' || return 130
      confirm "将所选节点绑定到 $out" && mutate bind_nodes "$out" "${ids[@]}";;
  esac
}

interactive_menu() {
  root_guard || return 1
  if ! dependencies; then
    say '首次使用需要先补齐依赖。'
    install_dependencies || return $?
  fi
  if [[ ! -x $SB_BIN ]]; then
    confirm '尚未安装核心，立即安装官方核心' || return 130
    install_core || return $?
  fi
  local initial_state
  initial_state=$(state_file) || initial_state=''
  if [[ -z $initial_state ]] || jq -e '.nodes|length==0' "$initial_state" >/dev/null; then
    say '尚无节点，接下来创建第一个节点；q 可取消并进入菜单。'
    if create_wizard && initial_state=$(state_file) && jq -e '.nodes|length>0' "$initial_state" >/dev/null; then
      if confirm '立即启动服务'; then
        lock_acquire && service_start
      fi
    fi
    cleanup
  fi
  main_menu
}
main_menu() {
  local choice id action
  while :; do
    say ''; say 'sing-box 部署与节点管理'
    say '1 创建节点'; say '2 查看节点和连接信息'; say '3 修改或删除节点'; say '4 设置中转和出口'; say '5 服务状态与故障检查'; say '6 核心与脚本管理'; say '7 使用帮助'; say '0 退出'
    ask choice '请选择' '' || return 0
    case "$choice" in
      1) create_wizard;;
      2)
        list_nodes; say '1 分享单个/全部；2 设置 DDNS 分享域名；3 清除分享域名；4 导出客户端 JSON；0 返回'
        ask action '选择' '' || return 0
        case "$action" in
          1) ask id '节点名称，all 全部' all && show_links "$id";;
          2) ask_valid id 'DDNS 域名（自行维护解析，CDN 节点不受全局域名覆盖）' '' valid_domain && mutate set_domain "$id";;
          3) confirm '清除全局分享域名' && mutate set_domain '';;
          4) ask_valid id '节点名称' '' valid_id && client_config "$id";;
        esac;;
      3)
        list_nodes; ask_valid id '节点名称' '' valid_id || return 0
        ask action '1 修改；2 删除；0 返回' '' || return 0
        case "$action" in
          1) txn_begin && node_wizard '' "$id" && confirm '保存节点修改' && txn_commit;;
          2) confirm "删除节点 $id" && mutate delete_resource node "$id";;
        esac;;
      4) outbound_menu;;
      5)
        show_status
        say '1 启动；2 停止；3 重启；4 日志；5 资源诊断；6 刷新公网缓存；0 返回'
        ask action '选择' '' || return 0
        case "$action" in
          1) lock_acquire && service_start;; 2) lock_acquire && service_stop;; 3) lock_acquire && service_restart;;
          4) show_logs;; 5) resources;; 6) refresh_network;;
        esac;;
      6)
        say '1 安装/更新固定稳定核心；2 卸载保留配置；3 卸载清理配置；4 核心版本；5 安装当前管理脚本；0 返回'
        ask action '选择' '' || return 0
        case "$action" in
          1) install_core;; 2) uninstall_core keep;; 3) uninstall_core purge;;
          4) [[ ! -x $SB_BIN ]] || "$SB_BIN" version;; 5) lock_acquire && save_manager && service_register;;
        esac;;
      7) usage;; 0) return 0;; '') ;; *) say '无效选项。';;
    esac
    cleanup
  done
}

usage() {
  cat <<'HELP'
sing-box 部署与节点管理
bash sing-box.sh                     交互菜单；q 取消，EOF 退出
bash sing-box.sh deps                安装发行版依赖（明确确认）
bash sing-box.sh install             官方固定稳定核心安装/更新
bash sing-box.sh status|resources|logs|refresh-network
bash sing-box.sh start|stop|restart|run-core
bash sing-box.sh list|outbounds|links [节点名|all]
bash sing-box.sh certificate 节点名   导出公开证书（不输出私钥）
bash sing-box.sh client-config 节点名 导出完整客户端 JSON（含认证信息、自签证书信任）
bash sing-box.sh check               校验当前配置
bash sing-box.sh check-private       私密终端检查当前配置
bash sing-box.sh check-private failed|clear  查看 / 清除最近一次失败诊断
bash sing-box.sh node-import 文件    批量导入节点对象数组
bash sing-box.sh outbound-import 文件
bash sing-box.sh link-import 名称    从标准输入读取一条分享链接
bash sing-box.sh bind 出口 节点...   direct 恢复直连；all 选择全部
bash sing-box.sh detour 出站 出口   修改出站链路（循环会拒绝）
bash sing-box.sh delete-node|delete-outbound 名称  需要明确确认
bash sing-box.sh domain 域名|-       DDNS 分享地址；- 清除
bash sing-box.sh uninstall keep|purge
bash sing-box.sh unlock              确认无管理进程后解除中断遗留锁
bash sing-box.sh recover             恢复中断的配置/核心事务

推荐 VLESS REALITY/Vision、VLESS WS TLS、Hysteria 2。
CDN 首版向导面向 Cloudflare：DNS 橙云、WebSocket、Full(strict)，
公网 HTTPS 端口 443/2053/2083/2087/2096/8443，另核对源站 NAT/防火墙。
源站证书仅供对应 CDN 信任；自签证书须在客户端导入信任，链接不跳过验证。
SOCKS5 有认证但没有传输加密；监听公网地址时注意网络可达范围。
默认不持续写核心流量日志；logs 查看有上限的管理日志。
故障排查：check-private；停止服务后可用 debug 在终端观察前台核心。
保存、check、启动、外网连通是不同状态；本工具不宣称自动验证外网。
HELP
}
show_logs() {
  local file
  for file in "$SB_ROOT/events.log.1" "$SB_ROOT/events.log"; do [[ ! -f $file ]] || tail -n 100 "$file"; done
  say '核心流量日志默认关闭，避免无上限写盘。使用 check-private 或前台 debug 排查。'
}
unlock() {
  local pid
  [[ -d $SB_ROOT/lock ]] || return 0
  if [[ -r $SB_ROOT/lock/pid ]]; then
    read -r pid < "$SB_ROOT/lock/pid"
    if [[ $pid =~ ^[0-9]+$ ]] && kill -0 "$pid" 2>/dev/null; then err '锁中的 PID 仍存活，拒绝解除。'; return 1; fi
  fi
  confirm '确认没有其他管理进程，删除遗留锁' || return 130
  rm -f "$SB_ROOT/lock/pid" && rmdir "$SB_ROOT/lock"
}
main() {
  local command=${1:-menu} file link rc=0 out
  shift || true
  [[ ${BASH_VERSINFO[0]} -ge 4 ]] || { err '需要 Bash 4 或更高版本。'; return 1; }
  case "$command" in help|-h|--help) usage; return 0;; esac
  if [[ $command == menu && ! -t 0 ]]; then
    if ! { exec 0</dev/tty; } 2>/dev/null; then
      err '菜单需要交互终端；自动化请使用明确的子命令。'; return 1
    fi
  fi
  if [[ $SB_ROOT == /etc/sb-manager && $(id -u) != 0 ]]; then err '管理系统部署需要 root。'; return 1; fi
  trap cleanup EXIT
  trap 'exit 130' INT
  trap 'exit 143' TERM HUP
  case "$command" in
    deps) install_dependencies; return $?;; run-core) run_core; return $?;;
    menu) interactive_menu; return $?;;
    logs) show_logs; return $?;;
    stop) lock_acquire && service_stop; return $?;;
    check-private)
      case "${1:-current}" in
        failed)
          [[ -f $SB_ROOT/last-check-error.log ]] || { err '没有已保存的失败诊断。'; return 1; }
          say '最近一次核心检查失败的诊断（可能含认证信息；不代表当前配置状态）：'
          cat "$SB_ROOT/last-check-error.log"; return $?;;
        clear) rm -f "$SB_ROOT/last-check-error.log"; return $?;;
        current) ;;
        *) err '用法：check-private [current|failed|clear]'; return 1;;
      esac;;
  esac
  dependencies || return 1
  case "$command" in
    install) install_core;; status) show_status;; resources) resources;; refresh-network) refresh_network;;
    list) list_nodes;; outbounds) list_outbounds;; links) show_links "${1:-all}";; certificate) export_certificate "${1:-}";;
    client-config) client_config "${1:-}";;
    start) lock_acquire && service_start;; restart) lock_acquire && service_restart;;
    check|check-private)
      file=$(current_generation) || return 1
      if [[ $command == check ]]; then check_core "$file/config.json"
      else "$SB_BIN" check -c "$file/config.json"; fi;;
    node-import) root_guard && mutate import_nodes "${1:-}";;
    outbound-import) root_guard && mutate put_outbound "${1:-}";;
    link-import)
      valid_id "${1:-}" || return 1
      IFS= read -r link || return 130
      root_guard && txn_begin && link_parse "$link" "$1" > "$SB_TXN/import.json" && put_outbound "$SB_TXN/import.json" && rm -f "$SB_TXN/import.json" && txn_commit;;
    bind) out=${1:-}; shift || return 1; mutate bind_nodes "$out" "$@";;
    detour) mutate set_detour "${1:-}" "${2:-}";;
    domain) local d=${1:-}; [[ $d != - ]] || d=''; mutate set_domain "$d";;
    delete-node) confirm "删除节点 ${1:-}" && mutate delete_resource node "${1:-}";;
    delete-outbound) confirm "删除出口 ${1:-}，引用节点恢复直连" && mutate delete_resource outbound "${1:-}";;
    uninstall) uninstall_core "${1:-keep}";; unlock) unlock;; recover) recover;;
    debug)
      lock_acquire || return 1
      service_running && { err '请先停止服务再前台诊断。'; return 1; }
      file=$(current_generation) || return 1
      jq '.log={level:"info",timestamp:true}' "$file/config.json" > "$SB_ROOT/debug.json" || return 1
      "$SB_BIN" run -c "$SB_ROOT/debug.json"; rc=$?; rm -f "$SB_ROOT/debug.json"; return "$rc";;
    *) err '未知命令；使用 help 查看用法。'; return 1;;
  esac
}
__SB_MANAGER_PAYLOAD__
SB_BUNDLE_PAYLOAD=${SB_BUNDLE_PAYLOAD%$'\n'}
source <(printf "%s\n" "$SB_BUNDLE_PAYLOAD") || return 1 2>/dev/null || exit 1
if [[ ${BASH_SOURCE[0]:-} == "$0" || ${#BASH_SOURCE[@]} == 0 ]]; then main "$@"; exit $?; fi
